import React, { useState } from "react";
import { motion } from "framer-motion";
import { ArrowLeft, ArrowRight } from "lucide-react";
import { useNavigate } from "react-router-dom";
import AnimationButton from "../components/layout/AnimationButton";

const TrayItem = ({ tray }) => {
  const [selectedImage, setSelectedImage] = useState(tray.mainImage);
const navigate = useNavigate();
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-100px" }}
      transition={{ duration: 0.5 }}
      className="border-b border-gray-200 pb-20 last:border-b-0"
    >
      {/* Heading */}
      <h2 className="text-4xl font-bold text-gray-900 mb-12 text-center">
        {tray.name}
      </h2>

      {/* Centered Content */}
      <div className="max-w-6xl mx-auto">
        <div className="grid lg:grid-cols-2 gap-16 items-start justify-center">
          {/* Image Column */}
          <div className="space-y-4 mx-auto lg:mx-0 max-w-md mt-20">
            <div className="aspect-5/3 border border-gray-200 rounded-lg overflow-hidden bg-gray-50">
              <img
                src={selectedImage}
                alt={tray.name}
                className="w-full h-full object-cover"
              />
            </div>

            <div className="grid grid-cols-3 gap-3 ">
              {tray.thumbnails.map((thumb, i) => (
                <button
                  key={i}
                  onClick={() => setSelectedImage(thumb)}
                  className={`aspect-square border rounded-md overflow-hidden bg-gray-50 transition ${
                    selectedImage === thumb
                      ? "border-gray-900"
                      : "border-gray-200 hover:border-gray-400"
                  }`}
                >
                  <img
                    src={thumb}
                    alt={`${tray.name} view ${i + 1}`}
                    className="w-full h-full object-cover"
                  />
                </button>
              ))}
            </div>
          </div>

          {/* Specifications */}
          <div className="mx-auto lg:mx-0 max-w-md w-full">
            <h3 className="text-xl font-semibold text-gray-900 mb-6 pb-3 border-b border-gray-300">
              Product Specifications
            </h3>

            <div className="border border-gray-200 rounded-lg overflow-hidden bg-white">
              {Object.entries(tray.details).map(([label, value], i) => (
                <div
                  key={i}
                  className={`grid grid-cols-2 gap-4 py-4 px-5 ${
                    i !== Object.entries(tray.details).length - 1
                      ? "border-b border-gray-200"
                      : ""
                  }`}
                >
                  <div className="text-sm font-medium text-gray-600">
                    {label}
                  </div>
                  <div className="text-sm font-medium text-gray-900">
                    {value}
                  </div>
                </div>
              ))}
            </div>
            <div className="mt-10 flex justify-center">
              <motion.button
              onClick={() => navigate('/contact')}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="btn-primary inline-flex items-center justify-center w-full md:w-auto px-6 py-3 bg-green-600 text-white font-semibold rounded-lg shadow-md hover:bg-green-700 hover:shadow-lg transition-all duration-300 cursor-pointer"
              >
                <AnimationButton>

                <span>Get Quote</span>
                <ArrowRight className="w-5 h-5 ml-2 group-hover:translate-x-1 transition-transform duration-300" />
                </AnimationButton>
              </motion.button>
            </div>
          </div>
        </div>
      </div>
    </motion.div>
  );
};

